                raise ValueError(
                    "`prompt_logprobs` are not available when `stream=True`.")

if prompt_logprobs < 0:
                raise ValueError("`prompt_logprobs` must be a positive value.")

        if (top_logprobs := data.get("top_logprobs")) is not None:
            if top_logprobs < 0:
